// ========== HÀM ĐỊNH DẠNG TIỀN ==========
function formatPrice(price) {
    return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(price);
}

// ========== HÀM ĐÓNG/MỞ MODAL ==========
function openModal(modalId) {
    document.getElementById(modalId).classList.add('open');
}
function closeModal(modalId) {
    document.getElementById(modalId).classList.remove('open');
}

// ========== SIDEBAR CLICK ==========
function filterSidebar(filterType) {
    // Đồng bộ với các nút filter-tabs
    document.querySelectorAll('.filter-btn').forEach(btn => {
        btn.classList.remove('active');
        if(btn.dataset.filter === filterType) {
            btn.classList.add('active');
        }
    });
    renderProducts(filterType, document.getElementById('searchInput').value);
    
    // Đổi tiêu đề
    const titles = {
        'all': 'Tất cả sản phẩm',
        'food': 'Thức ăn & Pate',
        'accessory': 'Phụ kiện & Đồ chơi',
        'dog': 'Dành cho Chó',
        'cat': 'Dành cho Mèo'
    };
    document.getElementById('categoryTitle').innerText = titles[filterType] || 'Sản phẩm';
}

