function openPolicy(type) {
    const policy = policies[type];
    if (!policy) return;
    document.getElementById('policyTitle').innerText = policy.title;
    document.getElementById('policyBody').innerHTML = policy.content;
    openModal('policyModal');
}

// ========== CHỨC NĂNG BLOG ==========
function openBlog(id) {
    const post = blogPosts[id];
    if (!post) return;
    
    document.getElementById('blogModalTitle').innerText = post.title;
    document.getElementById('blogModalDate').innerHTML = `<i class="far fa-calendar"></i> ${post.date}`;
    document.getElementById('blogModalImg').src = post.image;
    document.getElementById('blogModalBody').innerHTML = post.content;
    
    openModal('blogModal');
}

// ========== RENDER SẢN PHẨM ==========
function renderProducts(filter = 'all', searchQuery = '') {
    let filtered = products;

    if (filter !== 'all') {
        if (filter === 'dog' || filter === 'cat') {
            filtered = filtered.filter(p => p.category === filter);
        } else if (filter === 'food') {
            filtered = filtered.filter(p => p.type === 'food');
        } else if (filter === 'accessory') {
            filtered = filtered.filter(p => p.type === 'accessory');
        }
    }

    if (searchQuery) {
        filtered = filtered.filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()));
    }

    if (filtered.length === 0) {
        productGrid.innerHTML = '<p style="grid-column: 1/-1; text-align:center; color: var(--text-light); padding: 30px;">Không tìm thấy sản phẩm phù hợp.</p>';
        return;
    }

    productGrid.innerHTML = filtered.map(p => `
        <div class="product-card">
            <div class="product-img">
                <img src="${p.image}" alt="${p.name}">
                <div class="product-actions">
                    <button class="action-btn wishlist-btn" onclick="addToWishlist(${p.id})" title="Yêu thích">
                        <i class="fas fa-heart"></i>
                    </button>
                    <button class="action-btn view-btn" onclick="viewProduct(${p.id})" title="Xem nhanh">
                        <i class="far fa-eye"></i>
                    </button>
                    <button class="action-btn cart-btn" onclick="addToCart(${p.id})" title="Thêm vào giỏ">
                        <i class="fas fa-cart-plus"></i>
                    </button>
                </div>
            </div>
            <div class="product-info">
                <div class="product-category">${p.type === 'food' ? 'Thức ăn' : 'Phụ kiện'}</div>
                <h3 class="product-name">${p.name}</h3>
                <div class="product-price">${formatPrice(p.price)}</div>
            </div>
        </div>
    `).join('');
}

// ========== CHỨC NĂNG NÚT HOVER ==========
function addToWishlist(id) {
    const product = products.find(p => p.id === id);
    showToast(`❤️ Đã thêm "${product.name}" vào yêu thích!`);
}

function viewProduct(id) {
    const product = products.find(p => p.id === id);
    showToast(`👁️ Đang xem nhanh: ${product.name}`);
}

// ========== CHỨC NĂNG GIỎ HÀNG ==========
function addToCart(id) {
    const product = products.find(p => p.id === id);
    if (!product) return;

    const existing = cart.find(item => item.id === id);
    if (existing) {
        existing.quantity += 1;
    } else {
        cart.push({ ...product, quantity: 1 });
    }

    saveCart();
    updateCartUI();
    showToast(`Đã thêm "${product.name}" vào giỏ!`);
}

function saveCart() {
    localStorage.setItem('pawmart_cart', JSON.stringify(cart));
}

function updateCartUI() {
    const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);
    cartCountEl.textContent = totalItems;

    if (cart.length === 0) {
        cartItemsContainer.innerHTML = '<p style="text-align:center; color: var(--text-light); padding: 40px 0;">Giỏ hàng đang trống</p>';
        cartTotalPrice.textContent = '0đ';
        return;
    }

    cartItemsContainer.innerHTML = cart.map(item => `
        <div class="cart-item">
            <img src="${item.image}" alt="${item.name}" class="cart-item-img">
            <div class="cart-item-info">
                <div class="cart-item-name">${item.name}</div>
                <div class="cart-item-price">${formatPrice(item.price)}</div>
                <div class="cart-item-qty">
                    <button class="qty-btn" onclick="changeQty(${item.id}, -1)">-</button>
                    <span>${item.quantity}</span>
                    <button class="qty-btn" onclick="changeQty(${item.id}, 1)">+</button>
                </div>
            </div>
        </div>
    `).join('');

    const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
    cartTotalPrice.textContent = formatPrice(total);
}

function changeQty(id, delta) {
    const item = cart.find(i => i.id === id);
    if (!item) return;

    item.quantity += delta;
    if (item.quantity <= 0) {
        cart = cart.filter(i => i.id !== id);
    }

    saveCart();
    updateCartUI();
}

function checkout() {
    const currentUser = JSON.parse(localStorage.getItem('pawmart_user'));
    if (!currentUser) {
        showToast('Vui lòng đăng nhập để thanh toán!');
        closeModal('cartModal');
        openModal('authModal');
        return;
    }
    
    if (cart.length === 0) {
        showToast('Giỏ hàng của bạn đang trống!');
        return;
    }
    
    showToast('Thanh toán thành công! Cảm ơn bạn đã mua hàng.');
    cart = [];
    saveCart();
    updateCartUI();
    closeModal('cartModal');
}

// ========== CHỨC NĂNG ĐĂNG NHẬP / ĐĂNG KÝ ==========
if (!localStorage.getItem('pawmart_users')) {
    const demoUsers = [{ name: 'Quản trị viên', email: 'admin@pawmart.vn', password: '123456' }];
    localStorage.setItem('pawmart_users', JSON.stringify(demoUsers));
}

function switchAuthTab(tab) {
    document.getElementById('tabLogin').classList.toggle('active', tab === 'login');
    document.getElementById('tabRegister').classList.toggle('active', tab === 'register');
    document.getElementById('loginForm').classList.toggle('active', tab === 'login');
    document.getElementById('registerForm').classList.toggle('active', tab === 'register');
    document.getElementById('authTitle').innerText = tab === 'login' ? 'Đăng nhập' : 'Tạo tài khoản mới';
}

document.getElementById('loginForm').addEventListener('submit', (e) => {
    e.preventDefault();
    const email = document.getElementById('loginEmail').value;
    const password = document.getElementById('loginPassword').value;
    
    const users = JSON.parse(localStorage.getItem('pawmart_users')) || [];
    const user = users.find(u => u.email === email && u.password === password);

    if (user) {
        localStorage.setItem('pawmart_user', JSON.stringify(user));
        checkLoginStatus();
        closeModal('authModal');
        showToast(`Chào mừng ${user.name} trở lại!`);
        document.getElementById('loginForm').reset();
    } else {
        showToast('Email hoặc mật khẩu không đúng!');
    }
});

document.getElementById('registerForm').addEventListener('submit', (e) => {
    e.preventDefault();
    const name = document.getElementById('regName').value;
    const email = document.getElementById('regEmail').value;
    const password = document.getElementById('regPassword').value;
    
    let users = JSON.parse(localStorage.getItem('pawmart_users')) || [];
    
    if (users.find(u => u.email === email)) {
        showToast('Email này đã được đăng ký!');
        return;
    }

    const newUser = { name, email, password };
    users.push(newUser);
    localStorage.setItem('pawmart_users', JSON.stringify(users));
    
    localStorage.setItem('pawmart_user', JSON.stringify(newUser));
    checkLoginStatus();
    closeModal('authModal');
    showToast('Đăng ký thành công!');
    document.getElementById('registerForm').reset();
});

logoutBtn.addEventListener('click', (e) => {
    e.preventDefault();
    localStorage.removeItem('pawmart_user');
    checkLoginStatus();
    showToast('Đã đăng xuất!');
});

function checkLoginStatus() {
    const currentUser = JSON.parse(localStorage.getItem('pawmart_user'));
    
    if (currentUser) {
        userIcon.style.display = 'none';
        logoutBtn.style.display = 'block';
        userNameDisplay.style.display = 'inline';
        userNameDisplay.textContent = currentUser.name;
    } else {
        userIcon.style.display = 'block';
        logoutBtn.style.display = 'none';
        userNameDisplay.style.display = 'none';
        userNameDisplay.textContent = '';
    }
}

// ========== TOAST THÔNG BÁO ==========
function showToast(message) {
    const toast = document.createElement('div');
    toast.style.cssText = `
        position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%);
        background: var(--primary); color: white; padding: 12px 24px;
        border-radius: 30px; font-weight: 600; z-index: 10000;
        box-shadow: 0 4px 15px rgba(0,0,0,0.2); animation: fadeIn 0.3s;
    `;
    toast.textContent = message;
    document.body.appendChild(toast);
    setTimeout(() => { toast.style.opacity = '0'; toast.style.transition = '0.3s'; }, 2000);
    setTimeout(() => toast.remove(), 2300);
}

// ========== SỰ KIỆN KHÁC ==========
document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', () => {
        document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        renderProducts(btn.dataset.filter, document.getElementById('searchInput').value);
    });
});

document.getElementById('searchInput').addEventListener('input', (e) => {
    const activeFilter = document.querySelector('.filter-btn.active').dataset.filter;
    renderProducts(activeFilter, e.target.value);
});

document.getElementById('cartIcon').addEventListener('click', (e) => {
    e.preventDefault();
    openModal('cartModal');
    updateCartUI();
});

userIcon.addEventListener('click', (e) => {
    e.preventDefault();
    openModal('authModal');
});

// Đóng modal khi click ra ngoài vùng trắng
window.addEventListener('click', (e) => {
    if (e.target.classList.contains('modal-overlay')) {
        e.target.classList.remove('open');
    }
});

// ========== KHỞI TẠO ==========
renderProducts();
updateCartUI();
checkLoginStatus();